<?php
/** 0.17 regressions use the same real database adapter as the rest of the suite. */
use Chengyu\Services\{SearchIndex,Learning,Tracking,Reconciliation};
function content17(array $extra=[]): int {global $a,$admin;return $a->content->save(account($admin),array_merge(['kind'=>'article','title'=>'Index fixture '.key32(),'excerpt'=>'Public metadata','body'=>'BODY-NEVER-INDEX-017','protected_body'=>'SECRET-NEVER-INDEX-017','status'=>'published','access_level'=>'public'],$extra),true);}
function layout17(string $title): string{return json_encode(['format'=>'chengyu-layout','version'=>1,'blocks'=>[['id'=>'intro','type'=>'heading','title'=>$title]]]);}
function course17(string $access='public',int $media=0): array {global $a,$admin;$content=content17(['access_level'=>$access,'price'=>'1.00','price_currency'=>'balance']);$course=$a->learning->saveCourse(account($admin),['content_id'=>$content,'title'=>'Course fixture','description'=>'Safe public introduction','active'=>1]);$lesson=$a->learning->saveLesson(account($admin),['course_id'=>$course,'title'=>'Private lesson','body'=>'LESSON-SECRET-017','duration_seconds'=>120,'media_id'=>$media,'active'=>1]);return [$content,$course,$lesson];}
function shipment17(string $carrier='shunfeng',string $number='SF12345678'): array {global $a,$admin;$u=buyer16();$sale=buy16($u,product('physical','balance','10.00',3));$order=unit16($sale);$shipment=$a->tracking->attach($admin,['order_id'=>$order['id'],'revision'=>0,'carrier'=>$carrier,'tracking_number'=>$number]);return [$u,$sale,$order,$shipment];}
function statement17(array $rows): string {$s=fopen('php://temp','w+');fputcsv($s,Reconciliation::HEADER,',','"','');foreach($rows as $r){fputcsv($s,$r,',','"','');}rewind($s);$text=stream_get_contents($s);fclose($s);return $text;}
settings('modules',['courses_enabled'=>1,'support_enabled'=>1]);settings('commerce',['tracking_enabled'=>1]);settings('discovery',['search_engine'=>'portable']);
