test('017 layout drafts never change published output',static function()use($a,$admin){$slot='page10';$live=$a->layout->get($slot);$rev=$a->layout->draft($admin,$slot,layout17('Draft seventeen'),$live['revision'],0);same(1,$rev);same($live,$a->layout->get($slot));same('Draft seventeen',$a->layout->editor($slot)['document']['blocks'][0]['title']);reject(static function()use($a,$admin,$slot,$live){$a->layout->draft($admin,$slot,layout17('Lost edit'),$live['revision'],0);},409);$a->layout->discard($admin,$slot,1);same(0,$a->layout->editor($slot)['draft_revision']);});
test('017 layout publish restores history using a new revision, not stale overwrite',static function()use($a,$admin){$slot='page9';$live=$a->layout->get($slot);$r=$a->layout->publish($admin,$slot,layout17('First publication'),$live['revision'],0);$a->layout->draft($admin,$slot,layout17('Second publication'),$r,0);$next=$a->layout->publish($admin,$slot,layout17('Second publication'),$r,1);same($r+1,$next);same(0,$a->layout->editor($slot)['draft_revision']);$back=$a->layout->restore($admin,$slot,$r,$next);same($next+1,$back);same('First publication',$a->layout->get($slot)['document']['blocks'][0]['title']);reject(static function()use($a,$admin,$slot,$r,$next){$a->layout->restore($admin,$slot,$r,$next);},409);});
test('017 restored layout marks an existing draft stale',static function()use($a,$admin){$slot='page9';$r=$a->layout->get($slot)['revision'];$a->layout->draft($admin,$slot,layout17('Unpublished'),$r,0);$a->layout->restore($admin,$slot,$r,$r);truth($a->layout->editor($slot)['stale']);reject(static function()use($a,$admin,$slot,$r){$a->layout->publish($admin,$slot,layout17('Unpublished'),$r,1);},409);$a->layout->discard($admin,$slot,1);});
test('017 layout history retains only the latest twenty snapshots',static function()use($a,$admin){$slot='page8';$rev=$a->layout->get($slot)['revision'];for($i=0;$i<22;$i++){$rev=$a->layout->save($admin,$slot,layout17('Revision '.$i),$rev);}same(20,count($a->layout->history($slot)));same(20,(int)$a->db->value('SELECT COUNT(*) FROM cy_layout_history WHERE slot=?',[$slot]));});
