test('017 carrier query signs exact parameters and caches matching results without financial side effects',static function()use($a,$admin){[$u,$sale,$order,$shipment]=shipment17();$calls=0;$client=new \Chengyu\Core\HttpClient(static function($method,$url,$headers,$body)use(&$calls){$calls++;parse_str($body,$f);same('POST',$method);same('https://poll.kuaidi100.com/poll/query.do',$url);same(strtoupper(md5($f['param'].'fixture-key'.'fixture-customer')),$f['sign']);$p=json_decode($f['param'],true);same('123456789',$p['phone']);return response15(['status'=>'200','com'=>'shunfeng','nu'=>'SF12345678','state'=>'3','data'=>[['ftime'=>'2026-09-01 12:00:00','context'=>'Delivered by carrier']]]);});$service=new Tracking($a,$client);$before=funds($u);$service->refresh($admin,$shipment,'123456789');same(1,$calls);same('3',$service->view((int)$order['id'],account($u))['state']);same($before,funds($u));same('shipped',$a->db->value('SELECT fulfillment FROM cy_orders WHERE id=?',[$order['id']]));reject(static function()use($service,$admin,$shipment){$service->refresh($admin,$shipment,'123456789');},429);same(1,$calls);});
