test('017 statement parser rejects formulas, decimal minor units and duplicate references atomically',static function()use($a,$admin){$date=gmdate('Y-m-d\TH:i:s\Z');$row=['payment','CYFixture','pi_fixture','CNY','100','succeeded',$date];$start=time()-3600;$end=time()+3600;$n=(int)$a->db->value('SELECT COUNT(*) FROM cy_recon_batches');foreach(['formula','decimal','duplicate','currency','header'] as $case){$rows=[$row];if($case==='formula'){$rows[0][1]='=1+1';}if($case==='decimal'){$rows[0][4]='1.00';}if($case==='duplicate'){$rows[]=$row;}if($case==='currency'){$rows[0][3]='JPY';}$csv=statement17($rows);if($case==='header'){$csv='wrong,header' . "\n".$csv;}reject(static function()use($a,$admin,$csv,$start,$end){$a->reconciliation->import($admin,'stripe',$csv,$start,$end);});}same($n,(int)$a->db->value('SELECT COUNT(*) FROM cy_recon_batches'));});
