test('017 module switches deny new private and public feature entrypoints',static function()use($a){[$content,$course,$lesson]=course17();$u=buyer16();settings('modules',['courses_enabled'=>0,'support_enabled'=>0]);try{reject(static function()use($a,$course){$a->learning->course($course,null);},403);reject(static function()use($a,$u){$a->support->listing(account($u));},403);}finally{settings('modules',['courses_enabled'=>1,'support_enabled'=>1]);}});
test('017 Alipay desktop page-pay preserves the RSA2 signature and exact amount',static function()use($private16,$public16){$sale=gatewaySale16();$c=['alipay_direct_mode'=>'page','alipay_direct_appid'=>'fixtureapp','alipay_direct_private'=>$private16,'alipay_direct_public'=>$public16];$driver=new \Chengyu\Payments\Alipay($c,new \Chengyu\Core\HttpClient());$r=$driver->create($sale);parse_str(parse_url($r['url'],PHP_URL_QUERY),$fields);same('alipay.trade.page.pay',$fields['method']);$biz=json_decode($fields['biz_content'],true);same('FAST_INSTANT_TRADE_PAY',$biz['product_code']);same('12.00',$biz['total_amount']);$sig=$fields['sign'];unset($fields['sign']);ksort($fields);$pairs=[];foreach($fields as $k=>$v){$pairs[]=$k.'='.$v;}\Chengyu\Payments\Tools::rsaVerify(implode('&',$pairs),$sig,$public16);});
